import sys
from functools import lru_cache
from itertools import permutations

data = sys.stdin.read().split()
n = int(data[0])
cs = [tuple(int(data[1 + 3 * i + k]) for k in range(3)) for i in range(n)]
INF = 10 ** 18

@lru_cache(maxsize=None)
def best(prev, mask):
    res = 0
    for i in range(n):
        if mask >> i & 1:
            continue
        for p in set(permutations(cs[i])):
            if p[0] <= prev[0] and p[1] <= prev[1] and p[2] <= prev[2]:
                res = max(res, p[2] + best(p, mask | (1 << i)))
    return res

print(best((INF, INF, INF), 0))

